import java.time.LocalDate;

public final class Booking {
    private final String guest;
    private final Room room;
    private final LocalDate checkIn;
    private final int nights;

    private Booking(Builder b) {
        guest = b.guest;
        room = b.room;
        checkIn = b.from;
        nights = b.nights;
    }

    public static Builder forGuest(String guest) {
        return new Builder(guest);
    }

    public String guest() { return guest; }
    public Room room() { return room; }
    public LocalDate checkIn() { return checkIn; }
    public int nights() { return nights; }
    public LocalDate checkOut() { return checkIn.plusDays(nights); }

    public boolean overlaps(LocalDate from, LocalDate to) {
        return checkIn.isBefore(to) && from.isBefore(checkOut());
    }

    public static final class Builder {
        private final String guest;
        private Room room;
        private LocalDate from;
        private int nights;

        private Builder(String guest) { this.guest = guest; }

        public Builder room(Room room) { this.room = room; return this; }
        public Builder from(LocalDate from) { this.from = from; return this; }
        public Builder nights(int nights) { this.nights = nights; return this; }

        public Booking build() {
            if (room == null) throw new IllegalStateException("no room");
            if (from == null) throw new IllegalStateException("no check-in date");
            if (nights < 1) throw new IllegalStateException("at least one night");
            return new Booking(this);
        }
    }
}

solution.Hotel.java:
import java.io.*;
import java.time.LocalDate;
import java.util.*;

public class Hotel implements Iterable<Booking> {
    private final Map<String, Room> rooms = new TreeMap<>();
    private final List<Booking> bookings = new ArrayList<>();

    public void addRoom(Room room) {
        if (rooms.containsKey(room.number())) throw new IllegalArgumentException("room " + room.number() + " already exists");
        rooms.put(room.number(), room);
    }

    public void book(Booking booking) {
        if (!booking.room().equals(rooms.get(booking.room().number())))
            throw new IllegalArgumentException("no such room: " + booking.room());
        for (Booking other : bookings) {
            if (other.room().equals(booking.room()) && other.overlaps(booking.checkIn(), booking.checkOut()))
                throw new IllegalStateException("room " + booking.room().number() + " is taken");
        }
        bookings.add(booking);
    }

    public List<String> available(LocalDate from, LocalDate to, int guests) {
        List<String> free = new ArrayList<>();
        for (Room room : rooms.values()) {
            if (room.beds() < guests) continue;
            boolean taken = bookings.stream().anyMatch(b -> b.room().equals(room) && b.overlaps(from, to));
            if (!taken) free.add(room.number());
        }
        return free;
    }

    @Override
    public Iterator<Booking> iterator() {
        return new InOrder();
    }

    private class InOrder implements Iterator<Booking> {
        private final Iterator<Booking> sorted = bookings.stream()
                .sorted(Comparator.comparing(Booking::checkIn).thenComparing(Booking::guest))
                .toList()
                .iterator();
        public boolean hasNext() { return sorted.hasNext(); }
        public Booking next() { return sorted.next(); }
    }

    public byte[] save() throws IOException {
        var buffer = new ByteArrayOutputStream();
        try (var out = new DataOutputStream(buffer)) {
            out.writeInt(rooms.size());
            for (Room r : rooms.values()) {
                out.writeUTF(r.number());
                out.writeInt(r.beds());
            }
            out.writeInt(bookings.size());
            for (Booking b : bookings) {
                out.writeUTF(b.guest());
                out.writeUTF(b.room().number());
                out.writeLong(b.checkIn().toEpochDay());
                out.writeInt(b.nights());
            }
        }
        return buffer.toByteArray();
    }

    public static Hotel load(byte[] data) throws IOException {
        Hotel hotel = new Hotel();
        try (var in = new DataInputStream(new ByteArrayInputStream(data))) {
            int roomCount = in.readInt();
            for (int i = 0; i < roomCount; i++) hotel.addRoom(new Room(in.readUTF(), in.readInt()));
            int bookingCount = in.readInt();
            for (int i = 0; i < bookingCount; i++) {
                String guest = in.readUTF();
                Room room = hotel.rooms.get(in.readUTF());
                LocalDate checkIn = LocalDate.ofEpochDay(in.readLong());
                int nights = in.readInt();
                hotel.book(Booking.forGuest(guest).room(room).from(checkIn).nights(nights).build());
            }
        }
        return hotel;
    }
}

