LocalDate dec = LocalDate.of(2026, 12, 1);

test("builder rules", () -> {
    Booking b = Booking.forGuest("Ada").room(new Room("101", 2)).from(dec).nights(3).build();
    checkEq(b.checkOut(), LocalDate.of(2026, 12, 4));
    check(b.overlaps(LocalDate.of(2026, 12, 3), LocalDate.of(2026, 12, 5)), "shares the night of the 3rd");
    check(!b.overlaps(LocalDate.of(2026, 12, 4), LocalDate.of(2026, 12, 6)), "the check-out day is free");
    check(!b.overlaps(LocalDate.of(2026, 11, 28), dec), "ends the day Ada arrives");
    checkThrows(IllegalStateException.class, () -> Booking.forGuest("x").from(dec).nights(1).build());
    checkThrows(IllegalStateException.class, () -> Booking.forGuest("x").room(new Room("1", 1)).nights(1).build());
    checkThrows(IllegalStateException.class, () -> Booking.forGuest("x").room(new Room("1", 1)).from(dec).nights(0).build());
});

test("booking and availability", () -> {
    Hotel h = new Hotel();
    h.addRoom(new Room("102", 4));
    h.addRoom(new Room("101", 2));
    checkThrows(IllegalArgumentException.class, () -> h.addRoom(new Room("101", 3)));
    h.book(Booking.forGuest("Ada").room(new Room("101", 2)).from(dec).nights(3).build());
    checkEq(h.available(LocalDate.of(2026, 12, 2), LocalDate.of(2026, 12, 4), 2), List.of("102"));
    checkEq(h.available(LocalDate.of(2026, 12, 4), LocalDate.of(2026, 12, 5), 1), List.of("101", "102"));
    checkEq(h.available(dec, dec.plusDays(1), 3), List.of("102"));
    checkThrows(IllegalStateException.class, () -> h.book(Booking.forGuest("Bo").room(new Room("101", 2)).from(dec.plusDays(2)).nights(1).build()));
    checkThrows(IllegalArgumentException.class, () -> h.book(Booking.forGuest("Cy").room(new Room("999", 2)).from(dec).nights(1).build()));
    h.book(Booking.forGuest("Bo").room(new Room("101", 2)).from(dec.plusDays(3)).nights(2).build());
});

test("iteration order and saving", () -> {
    Hotel h = new Hotel();
    h.addRoom(new Room("101", 2));
    h.addRoom(new Room("102", 4));
    h.book(Booking.forGuest("Zoe").room(new Room("102", 4)).from(dec.plusDays(5)).nights(1).build());
    h.book(Booking.forGuest("Ada").room(new Room("101", 2)).from(dec).nights(2).build());
    h.book(Booking.forGuest("Bo").room(new Room("102", 4)).from(dec).nights(2).build());
    List<String> order = new ArrayList<>();
    for (Booking b : h) order.add(b.guest());
    checkEq(order, List.of("Ada", "Bo", "Zoe"));

    Hotel copy = Hotel.load(h.save());
    List<String> copied = new ArrayList<>();
    for (Booking b : copy) copied.add(b.guest() + " " + b.room().number() + " " + b.checkIn() + " " + b.nights());
    checkEq(copied, List.of("Ada 101 2026-12-01 2", "Bo 102 2026-12-01 2", "Zoe 102 2026-12-06 1"));
    checkEq(copy.available(dec, dec.plusDays(1), 1), List.of());
});

